-- Base schema: the "public" schema of the old Supabase database, generated by db/scripts/clean-dump.mjs
-- from a read-only pg_dump. Do not edit by hand; later changes go into new migrations.
-- Changes against the dump: role names in policies (authenticated -> tut_authenticated,
-- service_role -> tut_backend, PUBLIC -> tut_authenticated), FK auth.users -> public.app_user,
-- dump session settings removed.
