-- PostgreSQL database dump
--



SET LOCAL search_path = '';
SET LOCAL check_function_bodies = false;





--
-- Name: course_excluded_profile_ids(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_excluded_profile_ids(p_course_id integer) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT uc.profiles_id
  FROM public.user_course uc
  WHERE uc.course_id = p_course_id
    AND uc.is_excluded
    AND (
      public.is_admin()
      OR EXISTS (
        SELECT 1 FROM public.user_course me
        WHERE me.course_id = p_course_id
          AND me.profiles_id = auth.uid()
      )
    );
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.profiles (id, role, is_active)
  values (new.id, 'user', true)
  on conflict (id) do nothing;

  return new;
end;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin(_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = _uid
      and p.role = 'admin'
      and p.is_active = true
  );
$$;


--
-- Name: protect_profiles_auth_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_profiles_auth_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    NEW.auth_provider        := OLD.auth_provider;
    NEW.must_change_password := OLD.must_change_password;
    NEW.switch_edu_id_sub    := OLD.switch_edu_id_sub;
    NEW.role                 := OLD.role;
    NEW.email                := OLD.email;
    NEW.is_active            := OLD.is_active;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = timezone('utc', now());
  RETURN NEW;
END;
$$;


--
-- Name: sync_day_questionnaire_completed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_day_questionnaire_completed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE public.day
    SET day_questionnaire_completed = false
    WHERE day_id = OLD.day_id;
    RETURN OLD;
  END IF;

  UPDATE public.day
  SET day_questionnaire_completed = true
  WHERE day_id = NEW.day_id;
  RETURN NEW;
END;
$$;


--
-- Name: sync_profile_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_profile_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.profiles SET email = NEW.email WHERE id = NEW.id;
  RETURN NEW;
END;
$$;


