--
-- Name: time_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.time_entry (
    entry_id integer NOT NULL,
    day_id integer NOT NULL,
    start_time time without time zone NOT NULL,
    end_time time without time zone NOT NULL,
    primary_activity_id integer NOT NULL,
    secondary_activity_id integer,
    satisfaction_id integer,
    location_transport_id integer,
    digital_media_used boolean DEFAULT false NOT NULL,
    is_valid boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    meaningfulness_id integer,
    stressfulness_id integer,
    ict_attention_id integer,
    CONSTRAINT time_entry_check CHECK (((end_time > start_time) OR ((start_time = '23:50:00'::time without time zone) AND (end_time = '00:00:00'::time without time zone)))),
    CONSTRAINT time_entry_check1 CHECK ((((start_time + '00:10:00'::interval) = end_time) OR ((start_time = '23:50:00'::time without time zone) AND (end_time = '00:00:00'::time without time zone)))),
    CONSTRAINT time_entry_check2 CHECK (((secondary_activity_id IS NULL) OR (secondary_activity_id <> primary_activity_id)))
);


